import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {pathToFileURL} from 'node:url';
import path from 'node:path';

const root=new URL('../',import.meta.url);
export const dashboardBundleUrl=new URL('supabase/manual/api-proxy-v2.ts',root);
export async function renderDashboardBundle(){
  const read=async name=>(await readFile(new URL(name,root),'utf8')).replace(/^\uFEFF/,'').replace(/\r\n/g,'\n');
  const model=(await read('plan-model.mjs')).replace(/^export /gm,'');
  const policy=(await read('supabase/functions/api-proxy/policy.mjs')).replace(/^import [^\n]*\n/gm,'').replace(/^export /gm,'');
  const handler=(await read('supabase/functions/api-proxy/handler.mjs')).replace(/^import [^\n]*\n/gm,'').replace(/^export /gm,'');
  const entry=(await read('supabase/functions/api-proxy/index.ts')).replace(/^import [^\n]*\n/gm,'');
  return '// @ts-nocheck\n// Generated by scripts/build-dashboard-bundle.mjs. Edit the modular sources, then rebuild.\n// Paste this entire file into index.ts of the NEW api-proxy-v2 function in Supabase Dashboard.\n// No embedded secrets and no external imports. Microsoft/device authorization is performed below.\n\n'+model.trim()+'\n\n'+policy.trim()+'\n\n'+handler.trim()+'\n\n'+entry.trim()+'\n';
}
if(process.argv[1] && import.meta.url===pathToFileURL(path.resolve(process.argv[1])).href){
  await mkdir(new URL('supabase/functions/_shared/',root),{recursive:true});
  await writeFile(new URL('supabase/functions/_shared/plan-model.mjs',root),await readFile(new URL('plan-model.mjs',root)));
  await writeFile(dashboardBundleUrl,await renderDashboardBundle());
  console.log('Updated supabase/manual/api-proxy-v2.ts');
}
